-- Database-ready dataset generated from the uploaded Level-2 FPA DOCX.
-- Source content preserved in document order.

DROP TABLE IF EXISTS fpa_level2_source_rows;
CREATE TABLE fpa_level2_source_rows (
    id INTEGER PRIMARY KEY,
    source_order INTEGER NOT NULL,
    source_type VARCHAR(50) NOT NULL,
    content TEXT NOT NULL
);


-- Faculty Performance Index formula from the source:
-- FPI = 0.50 x SA + 0.30 x RBA + 0.10 x HPE + 0.10 x SF

CREATE VIEW IF NOT EXISTS fpa_level2_formula AS
SELECT 0.50 AS self_appraisal_weight,
       0.30 AS review_based_appraisal_weight,
       0.10 AS hod_principal_evaluation_weight,
       0.10 AS student_feedback_weight;